package com.bank.leak;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// LEAK: a static map that is only ever added to → every statement is immortal.
class StatementCacheLeak {
    private static final Logger log = Logger.getLogger(StatementCacheLeak.class.getName());
    // static → lives for the whole app; no eviction → unbounded growth
    private static final Map<String, byte[]> STATEMENT_CACHE = new HashMap<>();

    static void generateStatement(String accountId, int sizeKb) {
        // simulate building a statement blob and caching it forever
        STATEMENT_CACHE.put(accountId + "-" + System.nanoTime(), new byte[sizeKb * 1024]);
        if (STATEMENT_CACHE.size() % 500 == 0) {
            log.warning(() -> "STATEMENT_CACHE size=" + STATEMENT_CACHE.size()
                + " (never evicted → leak; bound with LinkedHashMap LRU or Caffeine)");
        }
    }

    // The FIX would be: a bounded cache, e.g. Caffeine maximumSize + expireAfterWrite,
    // or at minimum remove entries when the statement is no longer needed.
    static int cacheSize() { return STATEMENT_CACHE.size(); }
    static void clearForDemo() { STATEMENT_CACHE.clear(); }
}
