package com.bank.leak;

import java.util.logging.Logger;

// LEAK: ThreadLocal set on a POOLED thread but never removed → retained forever.
class UserContextLeak {
    private static final Logger log = Logger.getLogger(UserContextLeak.class.getName());
    private static final ThreadLocal<byte[]> CURRENT_USER = new ThreadLocal<>();

    // BAD: sets but never removes. On a pooled thread, the value outlives the request.
    static void handleRequestLeaky(String user) {
        CURRENT_USER.set(new byte[512 * 1024]);   // simulate a heavy user context (512KB)
        // ... process request for `user` ...
        // MISSING: CURRENT_USER.remove();  ← the leak
    }

    // GOOD: always remove in finally so the pooled thread does not retain it.
    static void handleRequestSafe(String user) {
        try {
            CURRENT_USER.set(new byte[512 * 1024]);
            // ... process request ...
        } finally {
            CURRENT_USER.remove();                 // ← prevents the leak
            log.fine(() -> "Cleared ThreadLocal for " + user);
        }
    }
}
