package com.bank.leak;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

public class LeakDemo {
    private static final Logger log = Logger.getLogger(LeakDemo.class.getName());

    public static void main(String[] args) throws Exception {
        log.info("Reproducing a static-cache leak and a ThreadLocal-in-pool leak");

        // Leak 1: keep generating statements into a static unbounded cache.
        for (int i = 0; i < 2000; i++) {
            StatementCacheLeak.generateStatement("SAV2001", 8);   // 8KB each, never freed
        }
        log.severe("Leak 1 retained " + StatementCacheLeak.cacheSize()
            + " statements that GC can NEVER reclaim (still reachable via static map)");

        // Leak 2: a FIXED pool of 4 threads, each retains its last ThreadLocal value.
        ExecutorService pool = Executors.newFixedThreadPool(4);
        for (int i = 0; i < 4; i++) {
            final String user = (i % 2 == 0) ? "Rajesh" : "Priya";
            pool.submit(() -> UserContextLeak.handleRequestLeaky(user));   // never removed
        }
        pool.shutdown();
        pool.awaitTermination(2, TimeUnit.SECONDS);
        log.severe("Leak 2: each of the 4 pooled threads still holds a 512KB user context"
            + " → fix with ThreadLocal.remove() in a finally block");

        StatementCacheLeak.clearForDemo();   // release so JVM survives the demo
    }
}
